import test from "node:test";
import assert from "node:assert/strict";
import {build,liveSource} from "./render.mjs";
import {extend,liveSource as businessLiveSource} from "./business.mjs";
import {verifyPublication} from "./integrity.mjs";
const origin="https://leogo.co.ke",id="12345678-1234-1234-1234-123456789012",id2="12345678-1234-1234-1234-123456789013";
const product={id,name:"New approved product",category:"groceries",category_name:"Groceries",availability:"available",regular_price_kes:110,current_price_kes:110,variants:[]};
const service={kind:"services",id:id2,partner_id:id,title:"New approved service",description:"Public service",location:"Siaya",price_from:100,pricing_model:"fixed"};
const pathP="seo-catalogue/products/"+id+"/index.html",pathS="seo-catalogue/business/services/"+id2+"/index.html";
function snapshot(products,businesses,images=[]){const f=extend(build(products,origin),businesses,origin,false,images);f["seo-catalogue/live.js"]=liveSource("sb_publishable_test");f["seo-catalogue/business/live.js"]=businessLiveSource("sb_publishable_test");return f;}
test("new products and services appear in both directories and sitemap, removed ones disappear",()=>{let f=snapshot([],[]);const before=verifyPublication(f,origin).urls;f=snapshot([product],[service]);assert.equal(verifyPublication(f,origin).urls,before+3);assert.ok(f[pathP]);assert.ok(f[pathS]);assert.ok(f["seo-catalogue/index.html"].includes("New approved product"));assert.ok(f["seo-catalogue/business/services/index.html"].includes("New approved service"));f=snapshot([{...product,name:"Renamed product"}],[{...service,title:"Renamed service"}]);assert.ok(f[pathP].includes("Renamed product"));assert.ok(f[pathS].includes("Renamed service"));f=snapshot([],[]);assert.ok(!f[pathP]&&!f[pathS]);assert.ok(!f["sitemap.xml"].includes(id));assert.equal(verifyPublication(f,origin).urls,before);});
test("publisher refuses missing pages, duplicate sitemap URLs and broken links",()=>{let f=snapshot([product],[service]);delete f[pathP];assert.throws(()=>verifyPublication(f,origin));f=snapshot([product],[service]);f["sitemap.xml"]=f["sitemap.xml"].replace("</urlset>","<url><loc>"+origin+"/</loc></url></urlset>");assert.throws(()=>verifyPublication(f,origin));f=snapshot([product],[service]);f[pathP]+='<a href="/seo-catalogue/missing/">Broken</a>';assert.throws(()=>verifyPublication(f,origin));});
test("staging combined preview has no production links and verifies",()=>{const f=extend(build([product],"https://staging.invalid",true),[service],"https://staging.invalid",true);assert.ok(Object.values(f).every(v=>!v.includes("leogo.co.ke")));assert.ok(f[pathP].includes("noindex,nofollow"));assert.ok(f[pathS].includes("noindex,nofollow"));assert.equal(verifyPublication(f,"https://staging.invalid").urls,12);});
